{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND (span_name LIKE 'SELECT ts.route%' OR span_name LIKE 'Transaction.commit') GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), quantile_cont(duration,0.5)/1e6, quantile_cont(duration,0.95)/1e6 FROM normal_traces WHERE service_name='ts-route-service' AND (span_name LIKE 'SELECT ts.route%' OR span_name LIKE 'Transaction.commit') GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Route-service's own DB spans (SELECT ts.route_*, Transaction.commit) rose from ~0.1ms p50 to 200-420ms p95."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('RouteController.queryAll','RouteController.queryById','RouteController.queryByIds') GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), quantile_cont(duration,0.5)/1e6, quantile_cont(duration,0.95)/1e6 FROM normal_traces WHERE service_name='ts-route-service' AND span_name IN ('RouteController.queryAll','RouteController.queryById','RouteController.queryByIds') GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Route controller handlers slowed in step with their DB calls, e.g. queryAll p50 rose from 4.7ms to 2750ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' src, metric, avg(value) avg_v, max(value) max_v FROM abnormal_metrics WHERE service_name='ts-route-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.cpu_limit_utilization') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, avg(value), max(value) FROM normal_metrics WHERE service_name='ts-route-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.cpu_limit_utilization') GROUP BY 1,2",
          "claim": "Route-service CPU and memory did not rise during the incident; they stayed flat or fell, so this is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
